import "next-auth";
import "next-auth/jwt";
declare module "next-auth" {
  interface Session {
    adminAuthAt?: number;
    adminAuthUserId?: string;
    user: {
      id: string;
      name?: string | null;
      email?: string | null;
      image?: string | null;
    };
  }
}
declare module "next-auth/jwt" {
  interface JWT {
    userId?: string;
    adminAuthAt?: number;
    adminAuthUserId?: string;
  }
}
